import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Opening: cooperate, then mirror immediately to punish an initial D.
    if n == 1:
        if op[0] == 'D':
            return 'D'
        return 'C'

    # Endgame: exploit. Cooperative opponents give more by being defected on.
    # Against almost-pure cooperators, defect; against defectors, defect anyway.
    rounds_left = 100 - n
    if rounds_left <= 2:
        if opp_rate > 0.9 and opp_d > 0:
            return 'D'
        if opp_rate > 0.95:
            return 'C'
        return 'D'

    # Almost always cooperative opponent: defect heavily but keep them at CC
    # occasionally to preserve the 3-per-round base when we can't do better.
    if n >= 10 and opp_rate >= 0.9:
        if opp_d == 0:
            # Never defected once: exploit hard, with rare cooperation to
            # avoid pathological all-D if something reacts.
            if n < 95:
                return 'D'
            return 'D'
        # Rare defections: still exploit, but don't nuke mutual cooperation.
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Almost always defecting opponent: defect, with rare C to test reactivity.
    if n >= 8 and opp_rate <= 0.12:
        if n < 90 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # Detect reactive TFT-like opponents via lag correlation: if opponent's
    # last action matches our second-to-last action, they're likely copying.
    if n >= 4:
        matches = 0
        for i in range(1, n):
            if op[i] == me[i - 1]:
                matches += 1
        lag_rate = matches / (n - 1)
    else:
        lag_rate = 0.0

    # Recent windows.
    w = 8 if n >= 8 else n
    recent_op = op[-w:]
    recent_me = me[-w:]
    recent_opp_c = 0
    for x in recent_op:
        if x == 'C':
            recent_opp_c += 1
    recent_my_c = 0
    for x in recent_me:
        if x == 'C':
            recent_my_c += 1
    recent_opp_d = w - recent_opp_c

    last_op = op[-1]
    last_me = me[-1]

    # Run lengths at end.
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    # Strong punishment of long opponent defection runs.
    if run_d >= 3:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent has been cooperating a long time and rate is high,
    # exploit opportunistically when safe (not against reactive opponents).
    if run_c >= 5 and opp_rate > 0.7 and lag_rate < 0.65:
        if n < 92 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # If opponent is likely reactive (TFT-like), cooperate when they do and
    # defect only once to re-establish, avoiding long DD spirals.
    if lag_rate >= 0.7 and opp_rate >= 0.4:
        if last_op == 'D' and run_d == 1 and rng.random() < 0.7:
            return 'C'
        if last_op == 'C':
            # Punish consecutive recent defections, otherwise cooperate.
            if recent_opp_d >= 3:
                return 'D'
            return 'C'
        return 'D'

    # General mixed regime.
    if opp_rate < 0.3:
        # Exploitative opponent: defect, rare probe.
        if n < 90 and rng.random() < 0.06:
            return 'C'
        return 'D'

    if opp_rate < 0.6:
        # Moderate: reciprocate with forgiveness; occasionally exploit.
        if last_op == 'D':
            if recent_opp_d >= 3:
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        else:
            if n < 90 and rng.random() < 0.08:
                return 'D'
            return 'C'

    # Opponent mostly cooperates (0.6 <= rate < 0.9): cooperate but probe.
    if last_op == 'D':
        # Forgive single defection, punish repeats.
        if recent_opp_d >= 3:
            return 'D'
        return 'C'

    # Opponent just cooperated.
    if n < 88 and rng.random() < 0.12:
        return 'D'
    return 'C'
